import { readFileSync } from "node:fs";

// The Claude Code PreToolUse guard's decision. PURE AND IMPORT-FREE: `kit hooks install`
// copies this file's source verbatim into the generated .githooks/claude-guard.mjs, which
// must run with nothing installed. Do not add an import here; the installer refuses one.
//
// It defends against accident and an agent's defaults, not against a person determined to
// get round it — the GitHub ruleset is the wall. It matches commands, not prose: heredoc
// bodies and quoted strings are removed first, and a pattern applies only where a command
// starts, so a commit message that says "never git push" is not a push. The price is that a
// command hidden inside a quoted string (`bash -c "git push"`) is not seen, which the
// ruleset still refuses.

// git, then any global options (`-C dir`, `-c k=v`, `--no-pager`), then the subcommand.
const GIT = String.raw`^git(?:\.exe)?(?:\s+(?:-[cC]\s+\S+|--?[A-Za-z][\w-]*(?:=\S+)?))*\s+`;
// A program at the start of a command, then any words before the subcommand.
const words = (program) => String.raw`^${program}(?:\.exe|\.cmd)?(?:\s+\S+)*?\s+`;
// `git tag` with a positional argument creates or deletes a tag; the list forms are fine.
const TAG_LIST = String.raw`(?:-l|--list|-n\d*|--contains|--no-contains|--points-at|--merged|--no-merged|-v|--verify)(?=[\s=]|$)`;

/** Each pattern a command (one segment, see `commandsIn`) may not match, with the reason and the command to use. */
const BLOCKED = new Map([
  [new RegExp(`${GIT}push\\b`), "pushes go through `kit push --yes` (gates, PR, CI dispatch); a raw `git push` is refused"],
  [
    new RegExp(`${GIT}tag\\b(?!.*\\s${TAG_LIST})(?=.*\\s[^\\s-])`),
    "tags are created by `kit merge` on a release PR; listing tags (`git tag -l`) is fine",
  ],
  [
    new RegExp(`${words("(?:npm|pnpm|yarn|bun)")}publish(?=$|\\s)`),
    "publishing is the release workflow's (release.yml on the tag); nothing publishes from a workstation",
  ],
  [new RegExp(`${words("gh")}pr\\s+merge\\b`), "merge with `kit merge` (it verifies the checks, syncs the default branch and tags a release)"],
  [new RegExp(`${words("gh")}workflow\\s+run\\b`), "`kit push` dispatches CI and `kit merge` dispatches ci.onMerge; do not dispatch by hand"],
]);

/**
 * The shell text with heredoc bodies removed (from the `<<[-]WORD` line to the line that is
 * exactly WORD) and every single- or double-quoted string replaced by `''`. Pure.
 */
function withoutProse(command) {
  const lines = String(command ?? "").replace(/\r\n?/g, "\n").split("\n");
  const kept = [];
  for (let i = 0; i < lines.length; i += 1) {
    kept.push(lines[i]);
    const terminators = [...lines[i].matchAll(/(?<!<)<<-?\s*(['"]?)(\w+)\1/g)].map((m) => m[2]);
    for (const word of terminators) {
      let j = i + 1;
      while (j < lines.length && lines[j].trim() !== word) j += 1;
      i = j; // skip the body and the terminator line
    }
  }
  const text = kept.join("\n");
  let out = "";
  for (let i = 0; i < text.length; i += 1) {
    const c = text[i];
    if (c === "\\" && i + 1 < text.length) {
      out += text[i + 1] === "\n" ? " " : "_";
      i += 1;
    } else if (c === "'") {
      const end = text.indexOf("'", i + 1);
      i = end === -1 ? text.length : end;
      out += "''";
    } else if (c === '"') {
      let j = i + 1;
      while (j < text.length && text[j] !== '"') j += text[j] === "\\" ? 2 : 1;
      i = j;
      out += "''";
    } else out += c;
  }
  return out;
}

/**
 * The commands in a shell line: split at `;`, `&&`, `||`, `|`, `&`, `(`, `$(`, `)`, `{`, `}`
 * and newlines, with leading env assignments (`FOO=bar git push`) and `exec`/`command`/`time`/
 * `sudo` prefixes removed. Pure.
 */
function commandsIn(command) {
  return withoutProse(command)
    .split(/&&|\|\||[;|&(){}\n]|\$\(/)
    .map((segment) => segment.trim().replace(/^(?:(?:[A-Za-z_]\w*=\S*|exec|command|time|sudo|nohup|!)\s+)*/, ""))
    .filter(Boolean);
}

/** `{ blocked: false }`, or `{ blocked: true, reason }` for the first pattern a command in `command` matches. */
function guardVerdict(command) {
  for (const segment of commandsIn(command)) {
    for (const [pattern, reason] of BLOCKED) {
      if (pattern.test(segment)) return { blocked: true, reason };
    }
  }
  return { blocked: false };
}

let input;
try {
  input = JSON.parse(readFileSync(0, "utf8"));
} catch {
  process.exit(0); // not a tool call we can read; the ruleset is the wall, not this
}
const verdict = guardVerdict(input?.tool_input?.command);
if (verdict.blocked) {
  process.stderr.write(`Blocked by kit's guard: ${verdict.reason}.\n`);
  process.exit(2);
}
process.exit(0);
